	public static async Task<bool> IsProxyAvailable(string targetUrl, string proxyAddress, string username, string password)
	{
		try
		{
			WebProxy webProxy = new WebProxy(proxyAddress);
			webProxy.Credentials = new NetworkCredential(username, password);
			HttpClientHandler val = new HttpClientHandler
			{
				Proxy = webProxy,
				UseProxy = true
			};
			HttpClient client = new HttpClient((HttpMessageHandler)(object)val);
			try
			{
				return (await client.GetAsync(targetUrl)).IsSuccessStatusCode;
			}
			finally
			{
				((IDisposable)client)?.Dispose();
			}
		}
		catch
		{
			return false;
		}
	}

